code.C:
#include <stdio.h>
#include <string.h>
int main() {
    char s[1000]; if (!fgets(s, sizeof(s), stdin)) return 0;
    char words[50][100]; int cnt = 0;
    char *tok = strtok(s, " \r\n");
    while (tok) { strcpy(words[cnt++], tok); tok = strtok(NULL, " \r\n"); }
    for (int i = cnt - 1; i >= 0; i--) {
        if (i < cnt - 1) putchar(' ');
        printf("%s", words[i]);
    }
    putchar('\n');
    return 0;
}

code.C++:
#include <iostream>
#include <string>
#include <vector>
#include <sstream>
using namespace std;
int main() {
    string s; if (!getline(cin, s)) return 0;
    stringstream ss(s);
    vector<string> w;
    string word;
    while (ss >> word) w.push_back(word);
    for (int i = (int)w.size() - 1; i >= 0; i--) {
        if (i < (int)w.size() - 1) cout << " ";
        cout << w[i];
    }
    cout << "\n";
    return 0;
}

code.Java:
import java.util.Scanner;
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLine()) {
            String[] w = sc.nextLine().trim().split("\\s+");
            StringBuilder sb = new StringBuilder();
            for (int i = w.length - 1; i >= 0; i--) {
                if (sb.length() > 0) sb.append(" ");
                sb.append(w[i]);
            }
            System.out.println(sb.toString());
        }
    }
}

